'use strict';
if(window.L){const p=new URLSearchParams(location.search);const lat=Number(p.get('lat')),lon=Number(p.get('lon')),zoom=Number(p.get('zoom'));if(Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180){const map=L.map('map',{scrollWheelZoom:false}).setView([lat,lon],zoom===4?4:12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);L.circleMarker([lat,lon],{radius:8,color:'#fff',weight:3,fillColor:'#b46143',fillOpacity:1}).addTo(map);document.getElementById('fallback').hidden=true}}
